function updatePanels(){const rates=factory.rates(),active=factory.cells.filter(e=>STRUCT[e.kind].power&&['operating','brownout'].includes(e.status)).length,stalled=factory.cells.filter(e=>STRUCT[e.kind].power&&['blocked','starved','unpowered','misconfigured','exhausted'].includes(e.status)).length,consumers=factory.cells.filter(e=>STRUCT[e.kind].power).length,total=factory.totalItems(),queued=factory.queueLength();$('deliveryRate').textContent=rates.delivery.toFixed(1);$('rateTrend').textContent=rates.delivery>0?'↑ '+fmt(sum(factory.delivered))+' items successfully dispatched':'Items are making their way to the docks';$('activeCount').textContent=active;$('stalledCount').textContent=stalled;$('activeBar').style.width=(active/Math.max(1,consumers)*100)+'%';$('stalledBar').style.width=(stalled/Math.max(1,consumers)*100)+'%';$('itemsCount').textContent=fmt(total);$('queueCount').textContent=fmt(queued);$('supplyValue').textContent=Math.round(factory.power.supply);$('demandValue').textContent=Math.round(factory.power.demand);$('drawValue').textContent=factory.power.draw.toFixed(1)+' kW';$('powerState').textContent=factory.power.factor>=.99?'STABLE':factory.power.supply>0?'BROWNOUT':'OFFLINE';$('powerState').style.color=factory.power.factor>=.99?'#a9bf8e':'#d4a877';$('powerBar').style.width=(factory.power.factor*100)+'%';drawChart($('throughputChart'),factory.history.slice(-60).map(h=>h.delivery*60),'#b5c48d');
 const produced=Object.entries(rates.produced).filter(([k,n])=>n>0||factory.stats.produced[k]);$('itemRates').innerHTML=(produced.length?produced.slice(0,6):[['ironOre',0],['ironPlate',0],['wire',0]]).map(([k,n])=>'<div class="itemrate"><span class="itemchip" style="color:'+ITEM[k].color+'">'+ITEM[k].symbol+'</span><span class="name">'+ITEM[k].name+'</span><span class="rate">'+n.toFixed(1)+' <small>/m</small></span></div>').join('');const issues=factory.bottlenecks();$('issueCount').textContent=issues.filter(i=>i.kind!=='healthy').length+' issues';$('bottleneckList').innerHTML=issues.slice(0,3).map(i=>'<div class="bottleneck '+i.severity+'"><span class="icon">'+icon(i.severity==='warn'?'warning':'check')+'</span><div><b>'+i.label+'</b><p>'+i.detail+'</p></div></div>').join('');
 const c=factory.contract,delivered=factory.delivered[c.item]||0;$('objectiveCard').classList.toggle('complete',c.complete);$('objectiveFill').style.width=Math.min(100,delivered/c.target*100)+'%';$('objectiveProgress').textContent=fmt(delivered)+' / '+fmt(c.target);$('objectiveEyebrow').textContent=factory.mode==='sandbox'?'Sandbox milestone':c.complete?'Contract fulfilled':'Active contract';$('contractChapter').textContent=String(c.stage).padStart(2,'0')+' / 03';$('objectiveTitle').textContent=c.complete?'Shipment complete':c.stage===1?'The first shipment':c.stage===2?'Connected components':'Built to move';$('objectiveDescription').textContent=c.complete?'Score '+fmt(c.score)+' · '+clock(factory.time)+' elapsed':'Deliver '+c.target+' '+ITEM[c.item].name.toLowerCase()+' to the loading docks.';$('nextContract').textContent=factory.mode==='sandbox'?'Milestone complete · keep building':c.stage<3?'Next contract →':'Campaign complete · start again';$('nextContract').disabled=factory.mode==='sandbox';$('modeTag').textContent=factory.mode==='sandbox'?'SANDBOX':'CONTRACT '+String(c.stage).padStart(2,'0');$('budgetLabel').textContent=factory.settings.cost?fmt(factory.budget)+' CR':'UNLIMITED';$('presetName').textContent=PRESETS[factory.presetId].name;$('seedLabel').textContent=factory.settings.seed;$('sizeLabel').textContent=factory.settings.w+' × '+factory.settings.h+' · ';$('fpsValue').textContent=Math.round(ui.fps);$('tickValue').textContent=String(factory.tick).padStart(6,'0');$('elapsedValue').textContent=clock(factory.time);$('structureCount').textContent=fmt(factory.cells.length);$('footerStatus').textContent=ui.paused?'PAUSED':'RUNNING';$('canvasStatus').textContent=ui.paused?'SIMULATION PAUSED':'SIMULATION LIVE';$('runLed').style.background=ui.paused?'#c3b583':'#9bbd91';$('systemLabel').textContent=ui.paused?'SYSTEM PAUSED':factory.power.supply===0?'POWER OFFLINE':'SYSTEM ONLINE';$('systemLed').style.background=ui.paused?'#c3b583':factory.power.supply===0?'#d59576':'#9bbd91';$('liveDiagnostics').classList.toggle('visible',ui.diagnostics);$('liveDiagnostics').textContent=Math.round(ui.fps)+' FPS · TICK '+factory.tick+' · '+ui.speed+'× · '+fmt(total)+' ITEMS\nRUN '+active+' · STALL '+stalled+' · '+Math.round(factory.power.supply)+' / '+Math.round(factory.power.demand)+' kW\nOUT '+rates.delivery.toFixed(1)+'/m · '+(STRUCT[ui.tool]?.name||ui.tool).toUpperCase()+' · '+delivered+'/'+c.target;$('liveDiagnostics').style.whiteSpace='pre-line';$('undoButton').disabled=!ui.undo.length;$('redoButton').disabled=!ui.redo.length;if(ui.inspectorTab==='inspect')updateInspector();if(ui.modal==='analytics')updateAnalytics();}
function layoutSnapshot(){return{budget:factory.budget,cells:factory.cells.map(e=>{const a={...e};delete a.network;return clone(a);})};}
function configKey(e){return JSON.stringify([e.kind,e.x,e.y,e.dir,e.level,e.recipe,e.limit,e.filter,e.throttle]);}
function commitEdit(before,includeState=false){const old=new Map(before.cells.map(e=>[e.id,e])),current=new Map(factory.cells.map(e=>[e.id,e])),changes=[];for(const id of new Set([...old.keys(),...current.keys()])){const a=old.get(id),b=current.get(id);if(!a||!b||configKey(a)!==configKey(b)||(includeState&&(JSON.stringify(a.input)!==JSON.stringify(b.input)||a.active!==b.active))){const raw=b?{...b}:null;if(raw)delete raw.network;changes.push({before:a||null,after:raw?clone(raw):null});}}if(changes.length){ui.undo.push({changes,beforeBudget:before.budget,afterBudget:factory.budget});if(ui.undo.length>40)ui.undo.shift();ui.redo=[];factory.dirty=true;autosaveSoon();beep('build');}updatePanels();}
function edit(fn){const before=layoutSnapshot();fn();commitEdit(before,true);}
function applyHistory(record,key){const ids=new Set(record.changes.map(c=>(c.before||c.after).id));factory.cells=factory.cells.filter(e=>!ids.has(e.id));for(const c of record.changes)if(c[key])factory.cells.push(clone(c[key]));factory.budget=Math.max(0,factory.budget+(key==='before'?record.beforeBudget-record.afterBudget:record.afterBudget-record.beforeBudget));factory.reindex();ui.selected=factory.cells.some(e=>e.id===ui.selected)?ui.selected:null;ui.selection=ui.selection.filter(id=>factory.cells.some(e=>e.id===id));renderInspector();autosaveSoon();}
function undo(){const rec=ui.undo.pop();if(!rec){toast('No construction to undo');return;}applyHistory(rec,'before');ui.redo.push(rec);toast('Construction undone');}
function redo(){const rec=ui.redo.pop();if(!rec){toast('No construction to redo');return;}applyHistory(rec,'after');ui.undo.push(rec);toast('Construction restored');}
function deleteArea(){const ids=ui.selection.length?ui.selection:ui.selected?[ui.selected]:[];if(!ids.length)return;edit(()=>{for(const id of ids){const e=factory.cells.find(e=>e.id===id);if(e)factory.remove(e.x,e.y);}ui.selection=[];ui.selected=null;renderInspector();});toast(ids.length+' structure'+(ids.length===1?'':'s')+' removed');}
function copyArea(){const entries=factory.cells.filter(e=>ui.selection.includes(e.id));if(!entries.length)return;const minX=Math.min(...entries.map(e=>e.x)),minY=Math.min(...entries.map(e=>e.y));setTool('copy');ui.blueprint=entries.map(e=>({dx:e.x-minX,dy:e.y-minY,kind:e.kind,dir:e.dir,recipe:e.recipe,filter:e.filter}));$('inspector').classList.remove('open');toast('Layout copied. Click an empty area to place '+entries.length+' structures.');}
function eyedrop(e){setTool(e.kind);ui.dir=e.dir;ui.recipe=e.recipe;$('inspector').classList.remove('open');toast(STRUCT[e.kind].name+' copied · '+['East','South','West','North'][ui.dir]);}
function beginMove(e){setTool('move');ui.moving=e;ui.dir=e.dir;$('inspector').classList.remove('open');toast('Click an empty cell to move the '+STRUCT[e.kind].name.toLowerCase());}
function rotateSelection(){const e=factory.cells.find(e=>e.id===ui.selected);if(e&&ui.tool==='inspect'){edit(()=>{for(const id of ui.selection.length?ui.selection:[e.id]){const item=factory.cells.find(e=>e.id===id);if(item)item.dir=(item.dir+1)%4;}renderInspector();});toast('Structure rotated');}else{ui.dir=(ui.dir+1)%4;toast('Build direction: '+['East →','South ↓','West ←','North ↑'][ui.dir]);}}
function place(kind,p,dir=ui.dir){if(kind==='belt'&&factory.at(p.x,p.y)?.kind==='belt'){factory.at(p.x,p.y).dir=dir;return true;}const options=ui.recipe&&RECIPES[ui.recipe]?.machine===kind?{recipe:ui.recipe}:{};const result=factory.add(kind,p.x,p.y,dir,options);if(result.ok){ui.effects.push({x:p.x,y:p.y,t:performance.now()});return true;}if(performance.now()-(ui.lastError||0)>800){toast(result.error,true);ui.lastError=performance.now();}return false;}
function route(a,b){const points=[{x:a.x,y:a.y}],xFirst=Math.abs(b.x-a.x)>=Math.abs(b.y-a.y);let x=a.x,y=a.y;const axisX=()=>{while(x!==b.x){x+=Math.sign(b.x-x);points.push({x,y});}},axisY=()=>{while(y!==b.y){y+=Math.sign(b.y-y);points.push({x,y});}};if(xFirst){axisX();axisY();}else{axisY();axisX();}return points;}
function dragAction(p){const drag=ui.drag;if(!drag)return;if(drag.type==='belt'){const path=route(drag.last,p);for(let i=0;i<path.length-1;i++){const a=path[i],b=path[i+1],dir=DIR.findIndex(v=>v[0]===b.x-a.x&&v[1]===b.y-a.y);if(dir>=0){place('belt',a,dir);place('belt',b,dir);drag.lastDir=dir;}}}else if(drag.type==='delete'){for(const cell of route(drag.last,p))factory.remove(cell.x,cell.y);}
 else if(drag.type==='power'){for(const cell of route(drag.last,p)){if(Math.hypot(cell.x-drag.lastPole.x,cell.y-drag.lastPole.y)>=4){if(!factory.at(cell.x,cell.y)&&place('pole',cell))drag.lastPole=cell;}}}drag.last=p;}
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',event=>{if(ui.modal)return;canvas.focus({preventScroll:true});$('tooltip').style.display='none';const p=screenCell(event.clientX,event.clientY);ui.pointerPositions.set(event.pointerId,p);canvas.setPointerCapture(event.pointerId);if(ui.pointerPositions.size===2){if(ui.drag?.before)commitEdit(ui.drag.before);const ps=[...ui.pointerPositions.values()];ui.drag={type:'pinch',distance:Math.hypot(ps[0].px-ps[1].px,ps[0].py-ps[1].py),center:{x:(ps[0].px+ps[1].px)/2,y:(ps[0].py+ps[1].py)/2}};return;}if(event.button===1||event.button===2||ui.space||ui.tool==='pan'){ui.drag={type:'pan',start:p,camera:{...ui.camera}};ui.spaceDragged=ui.space;canvas.style.cursor='grabbing';return;}
 if(event.shiftKey||ui.tool==='area'){ui.drag={type:'area',start:p,last:p};return;}
 if(ui.blueprint){const errors=ui.blueprint.map(b=>factory.placement(b.kind,p.x+b.dx,p.y+b.dy)).filter(Boolean),cost=ui.blueprint.reduce((a,b)=>a+STRUCT[b.kind].cost,0);if(errors.length||factory.settings.cost&&cost>factory.budget){toast(errors[0]||'Not enough credits for this layout',true);return;}edit(()=>{for(const b of ui.blueprint)factory.add(b.kind,p.x+b.dx,p.y+b.dy,b.dir,{recipe:b.recipe,filter:b.filter});});toast('Layout placed');return;}
 const entity=factory.at(p.x,p.y);if(ui.tool==='copy'){if(entity)eyedrop(entity);else toast('Click a structure to copy it');return;}if(ui.tool==='move'){if(!ui.moving){if(entity)beginMove(entity);return;}const moving=ui.moving,error=factory.placement(moving.kind,p.x,p.y);if(error&&entity?.id!==moving.id){toast(error,true);return;}edit(()=>{moving.x=p.x;moving.y=p.y;moving.dir=ui.dir;factory.reindex();ui.selected=moving.id;ui.selection=[moving.id];ui.moving=null;renderInspector();});toast('Structure moved');return;}
 if(ui.tool==='inspect'){ui.drag={type:'inspect',start:p,last:p};return;}
 if(['belt','pole','delete'].includes(ui.tool)){const before=layoutSnapshot();ui.drag={type:ui.tool==='pole'?'power':ui.tool,start:p,last:p,lastPole:p,lastDir:ui.dir,before};if(ui.tool==='delete')factory.remove(p.x,p.y);else if(ui.tool==='pole'){if(!entity)place('pole',p);}else place('belt',p);return;}
 if(STRUCT[ui.tool])edit(()=>place(ui.tool,p));});
canvas.addEventListener('pointermove',event=>{const p=screenCell(event.clientX,event.clientY);ui.hover=p;$('coordinateLabel').textContent='X '+p.x.toString().padStart(2,'0')+'  Y '+p.y.toString().padStart(2,'0');if(ui.pointerPositions.has(event.pointerId))ui.pointerPositions.set(event.pointerId,p);const drag=ui.drag;if(drag){$('tooltip').style.display='none';if(drag.type==='pinch'&&ui.pointerPositions.size===2){const ps=[...ui.pointerPositions.values()],distance=Math.hypot(ps[0].px-ps[1].px,ps[0].py-ps[1].py),center={x:(ps[0].px+ps[1].px)/2,y:(ps[0].py+ps[1].py)/2};if(drag.distance>0)zoom(distance/drag.distance,center.x,center.y);ui.camera.x+=center.x-drag.center.x;ui.camera.y+=center.y-drag.center.y;drag.distance=distance;drag.center=center;}else if(drag.type==='pan'){ui.camera.x=drag.camera.x+p.px-drag.start.px;ui.camera.y=drag.camera.y+p.py-drag.start.py;}else if(drag.type==='area'||drag.type==='inspect')drag.last=p;else if(p.x!==drag.last.x||p.y!==drag.last.y)dragAction(p);return;}
 const e=factory.at(p.x,p.y),tooltip=$('tooltip');if(e&&ui.tool==='inspect'){tooltip.innerHTML='<b>'+STRUCT[e.kind].name+'</b><br><span style="color:'+(['operating','idle','buffering'].includes(e.status)?'#b7c9a0':'#dfb280')+'">'+e.status+'</span> <span class="muted">· Level '+e.level+' · '+(e.items?.length||sum(e.input)+sum(e.output))+' items</span><br><span class="muted">Click to inspect'+(RECIPES[e.recipe]?' · '+RECIPES[e.recipe].name:'')+'</span>';tooltip.style.display='block';tooltip.style.left=Math.min(window.innerWidth-245,event.clientX+16)+'px';tooltip.style.top=Math.min(window.innerHeight-100,event.clientY+15)+'px';}else tooltip.style.display='none';});
function finishPointer(event){ui.pointerPositions.delete(event.pointerId);const drag=ui.drag;if(!drag)return;if(drag.type==='pinch'){ui.drag=null;ui.pointerPositions.clear();return;}if(drag.type==='inspect'&&Math.hypot(drag.last.px-drag.start.px,drag.last.py-drag.start.py)<10)selectEntity(factory.at(drag.start.x,drag.start.y));if(drag.type==='area'){const a=drag.start,b=drag.last;ui.selection=factory.cells.filter(e=>e.x>=Math.min(a.x,b.x)&&e.x<=Math.max(a.x,b.x)&&e.y>=Math.min(a.y,b.y)&&e.y<=Math.max(a.y,b.y)).map(e=>e.id);ui.selected=ui.selection[0]||null;setInspectorTab('inspect');renderInspector();if(viewW<900)$('inspector').classList.add('open');toast(ui.selection.length+' structures selected');}if(drag.type==='power'&&!factory.at(drag.last.x,drag.last.y))place('pole',drag.last);if(drag.before)commitEdit(drag.before);ui.drag=null;canvas.style.cursor=ui.tool==='pan'?'grab':ui.tool==='inspect'?'default':'crosshair';if(ui.selected&&!factory.cells.some(e=>e.id===ui.selected)){ui.selected=null;ui.selection=[];renderInspector();}}
canvas.addEventListener('pointerup',finishPointer);canvas.addEventListener('pointercancel',finishPointer);canvas.addEventListener('lostpointercapture',event=>{if(ui.drag&&ui.pointerPositions.has(event.pointerId))finishPointer(event);});canvas.addEventListener('pointerleave',()=>{if(!ui.drag)ui.hover=null;$('tooltip').style.display='none';});canvas.addEventListener('wheel',event=>{event.preventDefault();const p=screenCell(event.clientX,event.clientY);zoom(Math.exp(-event.deltaY*.0015),p.px,p.py);},{passive:false});
function togglePause(force){ui.paused=typeof force==='boolean'?force:!ui.paused;$('pauseText').textContent=ui.paused?'Resume':'Pause';$('pauseButton').setAttribute('aria-label',ui.paused?'Resume simulation':'Pause simulation');$('pauseButton').querySelector('.icon').innerHTML=icon(ui.paused?'play':'pause');ui.lastFrame=performance.now();updatePanels();beep();}
function singleStep(){togglePause(true);factory.step();updatePanels();render();}
document.addEventListener('keydown',event=>{if(event.target.closest('input,select,textarea')||event.ctrlKey&&event.key!=='z'&&event.key!=='y')return;if(event.key==='Escape'){if(ui.modal)closeModal();else{setTool('inspect');ui.selection=[];ui.selected=null;$('toolbox').classList.remove('open');$('inspector').classList.remove('open');renderInspector();}return;}if(ui.modal)return;if(event.code==='Space'){event.preventDefault();if(!event.repeat){ui.space=true;ui.spaceDragged=false;}return;}if(event.ctrlKey||event.metaKey){if(event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();}else if(event.key.toLowerCase()==='y'){event.preventDefault();redo();}return;}const key=event.key.toUpperCase();if(key==='R'){rotateSelection();return;}if(event.key==='.'||event.key==='>'){singleStep();return;}if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();deleteArea();return;}if(event.key==='0'){fitFactory();return;}if(event.key==='+'||event.key==='='){zoom(1.2);return;}if(event.key==='-'){zoom(1/1.2);return;}if(event.key.startsWith('Arrow')){event.preventDefault();ui.camera.x+=event.key==='ArrowLeft'?35:event.key==='ArrowRight'?-35:0;ui.camera.y+=event.key==='ArrowUp'?35:event.key==='ArrowDown'?-35:0;return;}const tool=Object.keys(shortcut).find(k=>shortcut[k]===key);if(tool)setTool(tool);});
document.addEventListener('keyup',event=>{if(event.code==='Space'){if(ui.space&&!ui.spaceDragged&&!ui.modal&&!event.target.closest('input,select,textarea'))togglePause();ui.space=false;}});window.addEventListener('blur',()=>{ui.space=false;ui.pointerPositions.clear();if(ui.drag?.before)commitEdit(ui.drag.before);ui.drag=null;});document.addEventListener('visibilitychange',()=>ui.lastFrame=performance.now());
function showModal(type,title,description,body,footer='',wide=false){ui.modal=type;ui.modalFocus=document.activeElement;$('modalTitle').textContent=title;$('modalDescription').textContent=description;$('modalEyebrow').textContent=type==='presets'?'Establish operations':type==='analytics'?'Live production intelligence':type==='archive'?'Local factory archive':type==='recipes'?'Manufacturing reference':'Factory controls';$('modalBody').innerHTML=body;$('modalFooter').innerHTML=footer;$('modalFooter').style.display=footer?'flex':'none';$('modal').classList.toggle('wide',wide);$('modalBack').hidden=false;$('tooltip').style.display='none';hydrateIcons($('modal'));$('closeModal').focus();$('analyticsButton').classList.toggle('active',type==='analytics');$('recipesButton').classList.toggle('active',type==='recipes');$('factoryTab').classList.toggle('active',!['analytics','recipes'].includes(type));beep();}
function closeModal(){ui.modal=null;$('modalBack').hidden=true;$('analyticsButton').classList.remove('active');$('recipesButton').classList.remove('active');$('factoryTab').classList.add('active');ui.modalFocus?.focus?.({preventScroll:true});ui.lastFrame=performance.now();}
$('modalBack').addEventListener('click',e=>{if(e.target===$('modalBack'))closeModal();});$('modalBack').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeModal();return;}if(e.key==='Tab'){const focusable=[...$('modal').querySelectorAll('button:not(:disabled),input:not([type=hidden]),textarea,select,[tabindex="0"]')].filter(el=>el.offsetParent!==null),first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
function openPresets(){ui.presetChoice=factory.presetId;ui.modeChoice=factory.mode;showModal('presets','Your next factory','Choose a scenario, then build your own solution. Every preset is a real, connected simulation.','<div class="modebuttons"><button id="campaignMode" class="'+(ui.modeChoice==='campaign'?'active':'')+'">Campaign · construction budget</button><button id="sandboxMode" class="'+(ui.modeChoice==='sandbox'?'active':'')+'">Sandbox · unlimited building</button></div><div class="presetgrid">'+Object.entries(PRESETS).map(([k,p])=>'<button class="presetcard '+(k===ui.presetChoice?'active':'')+'" data-preset="'+k+'"><div class="eyebrow" style="color:'+p.color+'">'+p.tag+'</div><span class="icon" data-icon="'+(k==='crisis'?'bolt':k==='stress'?'activity':k==='balanced'?'assembler':k==='congested'?'warning':k==='bus'?'network':'factory')+'"></span><b>'+p.name+'</b><p>'+p.desc+'</p></button>').join('')+'</div><div class="formgrid"><div><label class="fieldlabel" for="presetSeed">Deterministic seed</label><input id="presetSeed" class="field mono" type="number" min="0" max="4294967295" value="'+factory.settings.seed+'"></div><div><label class="fieldlabel" for="presetGrid">Construction area</label><select id="presetGrid" class="field"><option value="24">Compact · 24 × 20</option><option value="32" selected>Standard · 32 × 22</option><option value="48">Large · 48 × 32</option><option value="64">Industrial · 64 × 40</option></select></div></div><div class="errorline" id="presetError" role="alert"></div>','<span class="muted small">Throughput lab uses a 64 × 40 grid.<br>Named saves are kept when loading a scenario.</span><button class="textbtn primary" id="loadPreset"><span class="icon" data-icon="play"></span>Load factory</button>');if([24,32,48,64].includes(factory.settings.w))$('presetGrid').value=factory.settings.w;document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{ui.presetChoice=b.dataset.preset;document.querySelectorAll('[data-preset]').forEach(btn=>btn.classList.toggle('active',btn===b));beep();});$('campaignMode').onclick=()=>{ui.modeChoice='campaign';$('campaignMode').classList.add('active');$('sandboxMode').classList.remove('active');};$('sandboxMode').onclick=()=>{ui.modeChoice='sandbox';$('sandboxMode').classList.add('active');$('campaignMode').classList.remove('active');};$('loadPreset').onclick=()=>{const seed=Number($('presetSeed').value),w=Number($('presetGrid').value);if($('presetSeed').value===''||!Number.isInteger(seed)||seed<0||seed>4294967295){$('presetError').textContent='Enter a whole seed from 0 to 4,294,967,295.';return;}const next=new Factory({seed,w,h:w===24?20:w===32?22:w===48?32:40,cost:ui.modeChoice==='campaign'});next.loadPreset(ui.presetChoice);replaceFactory(next,null);closeModal();fitFactory();togglePause(false);toast(PRESETS[next.presetId].name+' loaded');autosaveSoon();};}
function openSettings(){showModal('settings','Simulation settings','Changes affect live production values. Time speed always uses the same fixed simulation ticks.','<div class="settingsrow"><div class="settingtext"><b>Conveyor speed</b><p>Cells per second. Controls actual item movement.</p></div><div class="rangegroup"><input id="beltSpeedInput" aria-label="Belt speed" type="range" min="0.5" max="3" step="0.1" value="'+factory.settings.beltSpeed+'"><output id="beltSpeedOutput">'+factory.settings.beltSpeed.toFixed(1)+'×</output></div></div><div class="settingsrow"><div class="settingtext"><b>Machine speed</b><p>Scales extraction and every recipe consistently.</p></div><div class="rangegroup"><input id="machineSpeedInput" aria-label="Machine speed" type="range" min="0.25" max="2" step="0.05" value="'+factory.settings.machineSpeed+'"><output id="machineSpeedOutput">'+factory.settings.machineSpeed.toFixed(2)+'×</output></div></div><div class="settingsrow"><div class="settingtext"><b>Item density</b><p>Conveyor capacity and packet spacing per cell.</p></div><select id="densityInput" class="field" aria-label="Item density">'+[1,2,3,4].map(n=>'<option value="'+n+'" '+(factory.settings.density===n?'selected':'')+'>'+n+' item'+(n>1?'s':'')+' / cell</option>').join('')+'</select></div><div class="settingsrow"><div class="settingtext"><b>Power difficulty</b><p>Changes the available generation per unit of fuel.</p></div><select id="powerDifficultyInput" class="field" aria-label="Power difficulty"><option value="0.7">Forgiving · 171 kW</option><option value="1">Standard · 120 kW</option><option value="1.6">Demanding · 75 kW</option></select></div><div class="settingsrow"><div class="settingtext"><b>Construction costs</b><p>Budgeted building or unlimited sandbox construction.</p></div><select id="costInput" class="field" aria-label="Construction cost mode"><option value="on">Budgeted campaign</option><option value="off">Unlimited sandbox</option></select></div><div class="divider"></div><div class="settingsrow"><div class="settingtext"><b>Seed & grid dimensions</b><p>Seed '+factory.settings.seed+' · '+factory.settings.w+' × '+factory.settings.h+' cells. Set these when loading a new scenario.</p></div><button id="settingsPreset" class="textbtn small">New factory</button></div><div class="settingsrow"><div class="settingtext"><b>Restart this factory</b><p>Reset items, inventories, elapsed time and contract progress.</p></div><button id="settingsReset" class="textbtn small">Restart</button></div>','<span class="muted small">All settings are included in saved factory state.</span><button id="settingsDone" class="textbtn primary">Done</button>');$('powerDifficultyInput').value=String(factory.settings.powerDifficulty);$('costInput').value=factory.settings.cost?'on':'off';$('beltSpeedInput').oninput=e=>{factory.settings.beltSpeed=Number(e.target.value);$('beltSpeedOutput').textContent=factory.settings.beltSpeed.toFixed(1)+'×';autosaveSoon();};$('machineSpeedInput').oninput=e=>{factory.settings.machineSpeed=Number(e.target.value);$('machineSpeedOutput').textContent=factory.settings.machineSpeed.toFixed(2)+'×';autosaveSoon();};$('densityInput').onchange=e=>{factory.settings.density=Number(e.target.value);autosaveSoon();};$('powerDifficultyInput').onchange=e=>{factory.settings.powerDifficulty=Number(e.target.value);autosaveSoon();};$('costInput').onchange=e=>{factory.settings.cost=e.target.value==='on';factory.mode=factory.settings.cost?'campaign':'sandbox';updatePanels();autosaveSoon();};$('settingsPreset').onclick=openPresets;$('settingsReset').onclick=openReset;$('settingsDone').onclick=closeModal;}
function openReset(){showModal('reset','Restart operations?','Return this scenario to its initial layout, inventory and contract progress. Named save slots remain available.','<div class="buffer"><div class="info-row"><span>Factory</span><b>'+PRESETS[factory.presetId].name+'</b></div><div class="info-row"><span>Elapsed time</span><b>'+clock(factory.time)+'</b></div><div class="info-row"><span>Delivered</span><b>'+fmt(sum(factory.delivered))+' items</b></div></div>','<button id="cancelReset" class="textbtn">Keep building</button><button id="confirmReset" class="textbtn primary"><span class="icon" data-icon="reset"></span>Restart factory</button>');$('cancelReset').onclick=closeModal;$('confirmReset').onclick=()=>{const stage=factory.contract.stage,next=new Factory({...factory.settings});next.loadPreset(factory.presetId);next.contract={stage,item:stage===1?(next.presetId==='stress'?'ironOre':'ironPlate'):stage===2?'circuit':'motor',target:stage===1?(next.presetId==='stress'?500:60):stage===2?30:16,complete:false,score:0};replaceFactory(next,null);togglePause(false);closeModal();fitFactory();autosaveSoon();toast('Factory restarted');};}
function openRecipes(){showModal('recipes','Recipe book','Exact material ratios. Machines commit their inputs when a batch starts and release outputs when it finishes.','<div class="recipelist">'+Object.entries(RECIPES).map(([k,r])=>'<article class="recipecard"><h3>'+r.name+'</h3><div class="machine">'+STRUCT[r.machine].name+' · '+r.time+' seconds · '+STRUCT[r.machine].power+' kW</div><div class="recipeequation">'+Object.entries(r.input).map(([k,n])=>'<span><span class="itemchip" style="color:'+ITEM[k].color+'">'+ITEM[k].symbol+'</span>'+n+' '+ITEM[k].name+'</span>').join('<span>+</span>')+'<span class="arrow">→</span>'+Object.entries(r.output).map(([k,n])=>'<span><span class="itemchip" style="color:'+ITEM[k].color+'">'+ITEM[k].symbol+'</span>'+n+' '+ITEM[k].name+'</span>').join('')+'</div></article>').join('')+'</div><p class="recipehelp">Select a machine in the factory to configure its recipe. Assemblers need both components. Power shortages slow every active batch; full output buffers apply backpressure through the line. Base durations shown above are modified by global machine speed, upgrades and available power.</p>','<span class="muted small">Extraction: 1 ore every 1.25 s · 8 kW.</span><button id="recipeDone" class="textbtn primary">Back to factory</button>',true);$('recipeDone').onclick=closeModal;}
function openGuide(){showModal('guide','A field guide to FERRO','A small factory. A lot of moving parts. Start with the live line, then make it your own.','<div class="guidelist"><div class="guideitem"><h3>01. Establish a supply</h3><p>Place an extractor over a colored ore deposit. Connect it to a smelter with conveyors. Deposits contain finite resources. Smelters turn ore into plates; fabricators turn plates into gears or wire.</p></div><div class="guideitem"><h3>02. Route with intention</h3><p>Drag the Conveyor tool across cells; corners route automatically. Rotate with R. A splitter alternates its forward and clockwise outputs. A merger combines incoming lanes. Inserters pull from behind and transfer forward.</p></div><div class="guideitem"><h3>03. Keep the lights on</h3><p>Generators consume one coal every 8 seconds. Feed them a coal line. Poles connect within 5.6 cells and supply machines within 4.35 cells. If demand exceeds supply, production slows. Inspect the power overlay to find disconnected consumers.</p></div><div class="guideitem"><h3>04. Ship and improve</h3><p>Delivery docks accept items instantly. Campaign contracts reward speed, a compact footprint and low energy use. Upgrades increase real speed and power demand. Sandbox gives you unlimited construction credits.</p></div><div class="guideitem"><h3>Read the bottlenecks</h3><p>Inspect a structure to see buffers, utilization and recent output. Congestion reveals full queues; blocked outputs reveal the start of a jam. Select recipes carefully: a machine only accepts its required ingredients.</p></div><div class="guideitem"><h3>Keep your progress</h3><p>The archive has three named slots and local autosave. Export complete JSON or share text to transfer a factory. Save an image of the current view with PNG export. Everything works offline.</p></div></div><div class="divider"></div><div class="keyboardgrid">'+[['Space','Pause / resume'],['Space + drag','Pan camera'],['R','Rotate'],['B','Draw conveyors'],['V / Esc','Inspect'],['Q','Eyedropper'],['H','Move structure'],['X','Drag erase'],['Shift + drag','Area selection'],['Ctrl Z / Y','Undo / redo'],['.','Single tick'],['0','Fit factory']].map(([k,v])=>'<span><kbd>'+k+'</kbd>'+v+'</span>').join('')+'</div><p class="recipehelp">Touch: choose Build to open the tool rail. One finger builds or selects, two fingers pan and pinch to zoom. Use the Pan camera tool to move the view with one finger. The Inspector drawer closes with its × control.</p>','<span class="muted small">No account. No server. Just your factory.</span><button id="guideDone" class="textbtn primary">Start building</button>');$('guideDone').onclick=closeModal;}
function openAnalytics(){showModal('analytics','Production overview','Live rates are measured over the last 30 simulation seconds. Charts show actual sampled factory state.','<div class="analyticscards"><div class="analyticscard"><h3>DELIVERY · ITEMS / MIN</h3><b id="analyticsDelivery">0</b><canvas id="analyticsDeliveryChart" class="spark"></canvas></div><div class="analyticscard"><h3>POWER · SUPPLY / DEMAND</h3><b id="analyticsPower">0 / 0</b><canvas id="analyticsPowerChart" class="spark"></canvas></div><div class="analyticscard"><h3>OUTPUT QUEUES · ITEMS</h3><b id="analyticsQueue">0</b><canvas id="analyticsQueueChart" class="spark"></canvas></div></div><table class="datatable"><thead><tr><th>Material</th><th>Produced /m</th><th>Consumed /m</th><th>In factory</th><th>Delivered</th></tr></thead><tbody id="analyticsRows"></tbody></table><div class="divider"></div><div class="metricgrid"><div><div class="value" id="analyticsUtil">0%</div><div class="label">Machine utilization</div></div><div><div class="value" id="analyticsBelt">0 /m</div><div class="label">Belt transfers</div></div><div><div class="value" id="analyticsEnergy">0 kWh</div><div class="label">Energy consumed</div></div><div><div class="value" id="analyticsFootprint">0 cells</div><div class="label">Factory footprint</div></div></div><div class="listtitle"><span>Live bottleneck detection</span></div><div id="analyticsBottlenecks"></div>','<span class="muted small">Rates scale with simulation time, preserving recipe ratios.</span><button id="analyticsDone" class="textbtn primary">Back to factory</button>',true);$('analyticsDone').onclick=closeModal;updateAnalytics();}
function updateAnalytics(){if(!$('analyticsRows'))return;const rates=factory.rates(),stock={};for(const e of factory.cells){for(const inv of[e.input,e.output,e.active?e.cycle?.input:null])for(const[k,n]of Object.entries(inv||{}))stock[k]=(stock[k]||0)+n;for(const i of e.items||[])stock[i.k]=(stock[i.k]||0)+1;}$('analyticsDelivery').textContent=rates.delivery.toFixed(1);$('analyticsPower').textContent=Math.round(factory.power.supply)+' / '+Math.round(factory.power.demand);$('analyticsQueue').textContent=factory.queueLength();drawChart($('analyticsDeliveryChart'),factory.history.map(h=>h.delivery*60),'#b8c991');drawChart($('analyticsPowerChart'),factory.history.map(h=>h.supply),'#becb8f',factory.history.map(h=>h.demand));drawChart($('analyticsQueueChart'),factory.history.map(h=>h.queue),'#d4af76');$('analyticsRows').innerHTML=Object.entries(ITEM).map(([k,i])=>'<tr><td><span class="itemchip" style="color:'+i.color+';margin-right:5px">'+i.symbol+'</span>'+i.name+'</td><td>'+rates.produced[k]?.toFixed(1)+'</td><td>'+rates.consumed[k]?.toFixed(1)+'</td><td>'+fmt(stock[k]||0)+'</td><td>'+fmt(factory.delivered[k]||0)+'</td></tr>').join('').replaceAll('undefined','0.0');const machines=factory.cells.filter(e=>STRUCT[e.kind].power);$('analyticsUtil').textContent=(sum(Object.fromEntries(machines.map(e=>[e.id,e.work])))/Math.max(1,sum(Object.fromEntries(machines.map(e=>[e.id,e.age]))))*100).toFixed(1)+'%';const throughput=factory.cells.filter(e=>e.items).reduce((a,e)=>a+e.history.slice(-30).reduce((n,h)=>n+h.flow,0),0)*60/Math.max(1,Math.min(30,factory.time));$('analyticsBelt').textContent=fmt(throughput)+' /m';$('analyticsEnergy').textContent=factory.stats.energy.toFixed(3)+' kWh';$('analyticsFootprint').textContent=factory.cells.length+' cells';$('analyticsBottlenecks').innerHTML=factory.bottlenecks().map(i=>'<div class="bottleneck '+i.severity+'"><span class="icon">'+icon(i.severity==='warn'?'warning':'check')+'</span><div><b>'+i.label+'</b><p>'+i.detail+'</p></div></div>').join('');}
function serialize(){return{app:'FERRO',version:1,factory:factory.dump(),view:{camera:{...ui.camera},paused:ui.paused,speed:ui.speed,overlay:ui.overlay,tool:ui.tool,dir:ui.dir}};}
function replaceFactory(next,view){factory=next;ui.undo=[];ui.redo=[];ui.selection=[];ui.selected=null;ui.hover=null;ui.drag=null;ui.moving=null;ui.blueprint=null;setTool(view?.tool||'inspect');ui.dir=view?.dir||0;if(view?.camera)ui.camera={...view.camera};if(view){ui.speed=view.speed;$('speedSelect').value=String(ui.speed);ui.overlay=view.overlay;$('overlaySelect').value=ui.overlay;togglePause(view.paused);}else{ui.overlay='none';$('overlaySelect').value='none';}setInspectorTab('overview');renderInspector();updatePanels();ui.lastFrame=performance.now();$('toolbox').classList.remove('open');$('inspector').classList.remove('open');$('resumeHint').classList.remove('visible');}
function decodeSave(data){const next=Factory.restore(data.factory||data);let view=data.view||null;if(view){const overlays=['none','flow','graph','power','utilization','congestion','blocked','status'];if(!view.camera||!Number.isFinite(view.camera.x)||!Number.isFinite(view.camera.y)||Math.abs(view.camera.x)>1e6||Math.abs(view.camera.y)>1e6||!Number.isFinite(view.camera.scale)||view.camera.scale<8||view.camera.scale>94||typeof view.paused!=='boolean'||![.5,1,2,4,8].includes(view.speed)||!overlays.includes(view.overlay)||!Object.keys(shortcut).includes(view.tool)||!Number.isInteger(view.dir)||view.dir<0||view.dir>3)throw Error('Invalid view or control settings');}return{next,view};}
function autosave(){try{localStorage.setItem('ferro.autosave',JSON.stringify({name:'Autosave',saved:Date.now(),state:serialize()}));$('autosaveLabel').textContent='SAVED LOCALLY';return true;}catch(error){$('autosaveLabel').textContent='SAVE UNAVAILABLE';return false;}}
function autosaveSoon(){clearTimeout(ui.saveTimer);ui.saveTimer=setTimeout(autosave,500);}
function readSlot(key){try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):null;}catch{return null;}}
function saveSlot(index){const name=$('slotName'+index).value.trim().slice(0,50)||'Factory '+(index+1);try{localStorage.setItem('ferro.slot.'+index,JSON.stringify({name,saved:Date.now(),state:serialize()}));toast('Saved “'+name+'”');beep('success');openArchive();}catch{toast('Local storage is full or unavailable. Export JSON to keep this factory.',true);}}
function loadSlot(key){try{const saved=readSlot(key);if(!saved?.state)throw Error('This save slot is empty');const{next,view}=decodeSave(saved.state);replaceFactory(next,view);closeModal();toast('Loaded “'+saved.name+'” · exact factory state restored');beep('success');autosaveSoon();}catch(error){toast('Could not load: '+error.message,true);}}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportJSON(){download(new Blob([JSON.stringify(serialize(),null,2)],{type:'application/json'}),'ferro-'+factory.presetId+'-'+factory.tick+'.json');toast('Complete factory JSON exported');}
function exportPNG(){const hover=ui.hover,selection=ui.selection,selected=ui.selected;ui.hover=null;ui.selection=[];ui.selected=null;render();canvas.toBlob(blob=>{if(blob){download(blob,'ferro-'+factory.presetId+'.png');toast('Factory view exported as PNG');}else toast('PNG export is unavailable',true);},'image/png');ui.hover=hover;ui.selection=selection;ui.selected=selected;}
function bytesToBase64(bytes){let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str);}
async function shareCode(){const bytes=new TextEncoder().encode(JSON.stringify(serialize()));if('CompressionStream'in window){const compressed=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());return'FERRO1G:'+bytesToBase64(compressed);}return'FERRO1:'+bytesToBase64(bytes);}
async function parseImport(text){text=text.trim();if(!text||text.length>8e6)throw Error('Enter a JSON factory or a share code under 8 MB');if(text.startsWith('FERRO1G:')||text.startsWith('FERRO1:')){const gzip=text.startsWith('FERRO1G:'),body=text.slice(gzip?8:7);let binary;try{binary=atob(body);}catch{throw Error('Share code is not valid base64');}let bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));if(gzip){if(!('DecompressionStream'in window))throw Error('This browser needs uncompressed JSON imports');const reader=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')).getReader(),parts=[];let total=0;while(true){const{value,done}=await reader.read();if(done)break;total+=value.byteLength;if(total>8e6){await reader.cancel();throw Error('Expanded factory exceeds 8 MB');}parts.push(value);}bytes=new Uint8Array(total);let offset=0;for(const part of parts){bytes.set(part,offset);offset+=part.length;}}text=new TextDecoder().decode(bytes);}let data;try{data=JSON.parse(text);}catch{throw Error('Invalid JSON. Paste a complete exported factory or FERRO share code.');}return decodeSave(data);}
async function importText(text){const errorEl=$('importError');try{const{next,view}=await parseImport(text);replaceFactory(next,view);if(!view){fitFactory();togglePause(true);}closeModal();toast('Factory imported · '+factory.cells.length+' validated structures');autosaveSoon();}catch(error){if(errorEl){errorEl.textContent=error.message;errorEl.classList.remove('successline');}else toast(error.message,true);beep('error');}}
function openArchive(){const slots=[0,1,2].map(i=>readSlot('ferro.slot.'+i)),auto=readSlot('ferro.autosave');showModal('archive','Save your factory','Complete inventories, in-flight items, recipes, power, seed and simulation timing are preserved.','<div class="archivegrid">'+slots.map((slot,i)=>'<div class="slot"><span class="slotmeta">0'+(i+1)+'</span><div class="slotinfo"><input id="slotName'+i+'" aria-label="Save slot '+(i+1)+' name" maxlength="50" value="'+escapeHTML(slot?.name||['Main factory','Experiment','Backup'][i])+'"><div class="timestamp">'+(slot?new Date(slot.saved).toLocaleString()+' · tick '+slot.state.factory.tick:'Empty save slot')+'</div></div><button data-save-slot="'+i+'" aria-label="Save slot '+(i+1)+'">Save</button><button data-load-slot="'+i+'" aria-label="Load slot '+(i+1)+'" '+(!slot?'disabled':'')+'>Load</button></div>').join('')+'</div><div class="info-row small"><span>Local autosave · every 15 seconds</span><button id="loadAuto" class="textbtn small" '+(!auto?'disabled':'')+'>Restore autosave</button></div><div class="divider"></div><div class="eyebrow">Export & transfer</div><div class="exportrow"><button id="exportJSON"><span class="icon" data-icon="download"></span>Export JSON</button><button id="exportPNG"><span class="icon" data-icon="image"></span>Export PNG</button><button id="shareFactory"><span class="icon" data-icon="link"></span>Create share code</button><button id="chooseImport"><span class="icon" data-icon="upload"></span>Import file</button></div><label class="fieldlabel" for="importText">Factory JSON or compact share code</label><textarea id="importText" class="field codefield" placeholder="Paste a saved factory or a FERRO1G: share code here…" spellcheck="false"></textarea><div class="errorline" id="importError" role="alert"></div>','<span class="muted small">Saves stay in this browser.<br>Export JSON for a portable backup.</span><button id="importFactory" class="textbtn primary"><span class="icon" data-icon="upload"></span>Import factory</button>');document.querySelectorAll('[data-save-slot]').forEach(b=>b.onclick=()=>saveSlot(Number(b.dataset.saveSlot)));document.querySelectorAll('[data-load-slot]').forEach(b=>b.onclick=()=>loadSlot('ferro.slot.'+b.dataset.loadSlot));$('loadAuto').onclick=()=>loadSlot('ferro.autosave');$('exportJSON').onclick=exportJSON;$('exportPNG').onclick=exportPNG;$('chooseImport').onclick=()=>{$('importFile').value='';$('importFile').click();};$('importFactory').onclick=() =>importText($('importText').value);$('shareFactory').onclick=async()=>{try{const code=await shareCode();if(ui.modal!=='archive')return;$('importText').value=code;$('importText').select();$('importError').textContent='Share code ready · '+fmt(code.length)+' characters. Copy the selected text.';$('importError').classList.add('successline');if(navigator.clipboard?.writeText)try{await navigator.clipboard.writeText(code);$('importError').textContent='Share code copied · '+fmt(code.length)+' characters.';}catch{}toast('Compact share code created');}catch(error){toast('Share code failed: '+error.message,true);}};}
$('importFile').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;if(file.size>8e6){toast('Import must be smaller than 8 MB',true);return;}try{await importText(await file.text());}catch(error){toast(error.message,true);}});
function nextContract(){if(factory.mode!=='campaign'||!factory.contract.complete)return;const stage=factory.contract.stage<3?factory.contract.stage+1:1,preset=stage===1?'starter':stage===2?'balanced':'bus',next=new Factory({...factory.settings,w:32,h:22,cost:true});next.loadPreset(preset);next.contract={stage,item:stage===1?'ironPlate':stage===2?'circuit':'motor',target:stage===1?60:stage===2?30:16,complete:false,score:0};replaceFactory(next,null);fitFactory();togglePause(false);toast('Contract '+stage+' started · '+next.contract.target+' '+ITEM[next.contract.item].name);beep('success');autosaveSoon();}
function bind(id,fn){$(id).addEventListener('click',fn);}
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));bind('factoryTab',()=>{if(ui.modal)closeModal();});bind('analyticsButton',openAnalytics);bind('overviewAnalytics',openAnalytics);bind('recipesButton',openRecipes);bind('helpButton',openGuide);bind('saveButton',openArchive);bind('presetButton',openPresets);bind('settingsButton',openSettings);bind('resetButton',openReset);bind('closeModal',closeModal);bind('pauseButton',()=>togglePause());bind('stepButton',singleStep);bind('undoButton',undo);bind('redoButton',redo);bind('zoomOut',()=>zoom(1/1.2));bind('zoomIn',()=>zoom(1.2));bind('fitButton',fitFactory);bind('overviewTab',()=>setInspectorTab('overview'));bind('inspectTab',()=>{setInspectorTab('inspect');renderInspector();});bind('diagnosticsButton',()=>{ui.diagnostics=!ui.diagnostics;updatePanels();});bind('nextContract',nextContract);bind('mobileBuild',()=>{$('toolbox').classList.toggle('open');$('inspector').classList.remove('open');});bind('mobileInspect',()=>{$('inspector').classList.toggle('open');$('toolbox').classList.remove('open');setInspectorTab('overview');});bind('closeTools',()=>$('toolbox').classList.remove('open'));bind('closeInspector',()=>$('inspector').classList.remove('open'));bind('soundButton',()=>{ui.sound=!ui.sound;if(ui.sound){enableAudio();beep('success');}$('soundButton').innerHTML='<span class="icon">'+icon(ui.sound?'sound':'soundoff')+'</span>';$('soundButton').setAttribute('aria-label',ui.sound?'Disable sound':'Enable sound');$('soundButton').title=ui.sound?'Disable sound':'Enable sound';toast(ui.sound?'Interface audio enabled':'Sound disabled');});$('speedSelect').onchange=e=>{ui.speed=Number(e.target.value);ui.lastFrame=performance.now();toast('Simulation speed '+ui.speed+'×');autosaveSoon();};$('overlaySelect').onchange=e=>{ui.overlay=e.target.value;autosaveSoon();};
try{const previous=readSlot('ferro.autosave');if(previous){decodeSave(previous.state);ui.pendingAutosave=previous;$('resumeHint').classList.add('visible');}}catch{}bind('resumeAutosave',()=>{try{const{next,view}=decodeSave(ui.pendingAutosave.state);replaceFactory(next,view);ui.pendingAutosave=null;toast('Previous autosave restored');}catch(error){toast(error.message,true);}});bind('dismissAutosave',()=>{$('resumeHint').classList.remove('visible');ui.pendingAutosave=null;});
new ResizeObserver(resize).observe($('canvasView'));window.addEventListener('resize',resize);
setInterval(()=>{if(!ui.pendingAutosave)autosave();},15000);
function frame(now){const elapsed=Math.max(0,Math.min(.25,(now-ui.lastFrame)/1000));ui.lastFrame=now;if(elapsed>0)ui.fps=.94*ui.fps+.06*Math.min(240,1/elapsed);if(!ui.paused&&!document.hidden)factory.advance(elapsed,ui.speed);render();if(now-ui.lastPanelUpdate>250){ui.lastPanelUpdate=now;updatePanels();}requestAnimationFrame(frame);}
window.Ferro={get factory(){return factory;},get camera(){return{...ui.camera};},get audio(){return{enabled:ui.sound,state:audioContext?.state||'not-created'};},cellToScreen:cellScreen,snapshot:serialize,diagnostics:()=>({tick:factory.tick,time:factory.time,paused:ui.paused,speed:ui.speed,fps:ui.fps,tool:ui.tool,activeItems:factory.totalItems(),power:{...factory.power},delivered:{...factory.delivered},produced:{...factory.stats.produced},consumed:{...factory.stats.consumed},queue:factory.queueLength(),operating:factory.cells.filter(e=>STRUCT[e.kind].power&&['operating','brownout'].includes(e.status)).length,stalled:factory.cells.filter(e=>STRUCT[e.kind].power&&['starved','blocked','unpowered'].includes(e.status)).length,objective:{...factory.contract}})};
